def luhn_valid(num):
    digits = [int(c) for c in num]
    total = 0
    for i, d in enumerate(reversed(digits)):
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0

def pascal_row(n):
    row = [1]
    for _ in range(n):
        row = [a + b for a, b in zip([0] + row, row + [0])]
    return row

def ipv4_valid(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p or not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':
            return False
        if int(p) > 255:
            return False
    return True

def merge_intervals(iv):
    if not iv:
        return []
    iv = sorted(iv)
    out = [list(iv[0])]
    for s, e in iv[1:]:
        if s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out

def roman_to_int(s):
    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i, ch in enumerate(s):
        v = vals[ch]
        if i + 1 < len(s) and vals[s[i + 1]] > v:
            total -= v
        else:
            total += v
    return total

def caesar_crack(cipher, word):
    def shift_text(t, k):
        out = []
        for c in t:
            if c.isalpha():
                out.append(chr((ord(c) - 97 - k) % 26 + 97))
            else:
                out.append(c)
        return ''.join(out)
    for k in range(26):
        if word in shift_text(cipher, k):
            return k
    return -1

def parse_csv_line(line):
    out, cur, i = [], [], 0
    in_q = False
    while i < len(line):
        c = line[i]
        if in_q:
            if c == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    cur.append('"')
                    i += 2
                    continue
                in_q = False
            else:
                cur.append(c)
        else:
            if c == '"':
                in_q = True
            elif c == ',':
                out.append(''.join(cur))
                cur = []
            else:
                cur.append(c)
        i += 1
    out.append(''.join(cur))
    return out

def histogram(counts):
    items = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return '\n'.join(f'{k}: ' + '*' * v for k, v in items)
